const spend = $('LiteLLM spend by model').all().map(x => x.json);
const publish = $('Publish last month').all().map(x => x.json);
const cskh = $('CSKH last month').all().map(x => x.json);
const fmt = (rows, keys) => rows.length ? rows.map(r => keys.map(k => `${k}=${r[k]}`).join(' ')).join('\n') : '(empty)';
const total = spend.reduce((a, r) => a + Number(r.spend_usd || 0), 0).toFixed(4);
const text = [
  `*Monthly automation review*`,
  ``,
  `*Total LLM spend:* $${total}`,
  '```',
  fmt(spend.slice(0, 10), ['model','requests','spend_usd','avg_cost_per_req']),
  '```',
  `*Publish outcomes (automated_attempts excludes manual_required):*`,
  '```',
  fmt(publish, ['platform','automated_attempts','successes','failures','manual_required']),
  '```',
  `*CSKH intents (leads=intent=lead_qualified, handoffs=action_taken=handoff):*`,
  '```',
  fmt(cskh, ['intent','messages','leads','handoffs','auto_replies','staff_approved','staff_rejected']),
  '```'
].join('\n');
return [{ json: { text } }];
